// QueryPromptOverride Configuration for customizing query prompts.
//
// This allows you to customize how responses are generated during query operations.
// Query prompts guide the LLM on how to format and style responses, what tone to use,
// and how to incorporate retrieved information into the response.
//
// Required placeholders:
// - {question}: Will be replaced with the user's query
// - {context}: Will be replaced with the retrieved content/context
//
// Example prompt template:
// ```
// Answer the following question based on the provided information.
//
// Question: {question}
//
// Context:
// {context}
//
// Answer:
// ```
type QueryPromptOverride struct {
	// PromptTemplate Custom prompt template for generating responses to queries. REQUIRED PLACEHOLDERS: {question} and {context} must be included in the template. The {question} placeholder will be replaced with the user query, and {context} will be replaced with the retrieved content. Use this to control response style, format, and tone.
	PromptTemplate *string `json:"prompt_template,omitempty"`

	// SystemPrompt Custom system prompt that replaces Morphik's default query agent instructions. Use this to fully control the assistant's behavior when generating responses.
	SystemPrompt *string `json:"system_prompt,omitempty"`
}

// QueryPromptOverrides Container for query-related prompt overrides.
//
// Use this class when customizing prompts for query operations, which may
// include customizations for entity extraction, entity resolution, and
// the query/response generation itself.
//
// This is the most feature-complete override class, supporting all customization types.
//
// Available customizations:
// - entity_extraction: Customize how entities are identified in text
// - entity_resolution: Customize how entity variants are grouped
// - query: Customize response generation style, format, and tone
//
// Each type has its own required placeholders. See the specific class documentation
// for details and examples.
type QueryPromptOverrides struct {
	// EntityExtraction Overrides for entity extraction prompts - controls how entities are identified in text during queries
	EntityExtraction *EntityExtractionPromptOverride `json:"entity_extraction,omitempty"`

	// EntityResolution Overrides for entity resolution prompts - controls how variant forms are grouped during queries
	EntityResolution *EntityResolutionPromptOverride `json:"entity_resolution,omitempty"`

	// Query Overrides for query prompts - controls response generation style, format, and tone
	Query *QueryPromptOverride `json:"query,omitempty"`
}

